// heptagonGeometry.js
// Geometry helper for Duval Heptagon 2 diagram

const HEPTAGON_CENTER = [342.4, 381];
const HEPTAGON_RADIUS = 348;
const HEPTAGON_SIDES = 7;
const HEPTAGON_START_ANGLE = -90; // start from top
const HEPTAGON_ZONE_POINTS = {
  D2: [[123.26, 218.8], [342.4, 94.81], [397.18, 233.38], [362.94, 371.95], [123.26, 371.95]],
  D1: [[82.18, 474.06], [123.26, 371.95], [362.94, 371.95], [273.92, 656.39], [109.57, 554.28]],
  TD: [[362.94, 371.95], [397.18, 233.38], [568.38, 364.66], [458.82, 649.09], [273.92, 656.39]],
  LCCD: [[397.18, 233.38], [458.82, 189.62], [588.93, 284.43], [568.38, 364.66]],
  MCCD: [[458.82, 189.62], [499.9, 153.16], [595.78, 211.5], [588.93, 284.43]],
  HCCD: [[499.9, 153.16], [561.54, 138.57], [609.47, 189.62], [595.78, 211.5]],
  T3: [[458.82, 649.09], [568.38, 364.66], [527.3, 430.3], [493.06, 649.09]],
  T2: [[493.06, 649.09], [527.3, 444.89], [547.84, 430.3], [540.99, 517.82], [520.45, 598.04]],
  T1: [[540.99, 517.82], [547.84, 430.3], [616.32, 459.47], [582.08, 561.58]],
  PD: [[232.83, 627.22], [445.12, 619.92], [349.25, 707.44], [184.9, 707.44]],
};

// Vertex order (clockwise from top): CO, CO2, C2H4, H2, CH4, C2H2, C2H6
const VERTEX_NAMES = ["CO", "CO2", "C2H4", "H2", "CH4", "C2H2", "C2H6"];
const HEPTAGON_LABEL_LAYOUT = [
  { radialOffset: 30, nudge: [-2, -15], textAnchor: "middle" },
  { radialOffset: 16, nudge: [-2, -10], textAnchor: "start" },
  { radialOffset: 18, nudge: [-6, 4], textAnchor: "start" },
  { radialOffset: 24, nudge: [-5, 30], textAnchor: "middle" },
  { radialOffset: 24, nudge: [5, 31], textAnchor: "middle" },
  { radialOffset: 18, nudge: [6, 4], textAnchor: "end" },
  { radialOffset: 16, nudge: [-1, -10], textAnchor: "end" },
];

// ==========================
// Create Regular Heptagon
// ==========================
function createRegularPolygonPoints(centerX, centerY, radius, sides, startAngleDeg) {
  const points = [];
  const step = (Math.PI * 2) / sides;
  const startAngle = (startAngleDeg * Math.PI) / 180;

  for (let i = 0; i < sides; i += 1) {
    const angle = startAngle + i * step;
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);
    points.push([x, y]);
  }

  return points;
}

// ==========================
// Convert points → SVG path
// ==========================
function pointsToPath(points) {
  return points
    .map((point, index) =>
      `${index === 0 ? "M" : "L"} ${point[0].toFixed(2)} ${point[1].toFixed(2)}`
    )
    .join(" ")
    .concat(" Z");
}

// ==========================
// Heptagon Outer
// ==========================
export function getHeptagonOuterPoints() {
  return createRegularPolygonPoints(
    HEPTAGON_CENTER[0],
    HEPTAGON_CENTER[1],
    HEPTAGON_RADIUS,
    HEPTAGON_SIDES,
    HEPTAGON_START_ANGLE
  );
}

export function getHeptagonOuterPath() {
  return pointsToPath(getHeptagonOuterPoints());
}

// ==========================
// Vertex labels (corner gas names)
// ==========================
export function getHeptagonLabelPoints() {
  const points = getHeptagonOuterPoints();

  return points.map((point, index) => ({
    label: VERTEX_NAMES[index],
    point,
    ...HEPTAGON_LABEL_LAYOUT[index],
  }));
}

// ==========================
// Zone labels inside the heptagon
// ==========================
export function getHeptagonZoneLabels() {
  return [
    { zone: "PD", point: [220, 700] },
    { zone: "D1", point: [155, 435] },
    { zone: "D2", point: [245, 215] },
    { zone: "TD", point: [375, 498] },
    { zone: "T3", point: [478, 548] },
    { zone: "T2", point: [552, 518] },
    { zone: "T1", point: [610, 520] },
    { zone: "LCCD", point: [462, 260] },
    { zone: "MCCD", point: [539, 218] },
    { zone: "HCCD", point: [565, 152] },
  ];
}

export function getHeptagonPaths() {
  return Object.entries(HEPTAGON_ZONE_POINTS).map(([zone, points]) => ({
    zone,
    path: pointsToPath(points),
  }));
}

// ==========================
// Marker (weighted centroid)
// Gas → vertex mapping: CO, CO2, C2H4, H2, CH4, C2H2, C2H6
// ==========================
export function getHeptagonMarker(values) {
  const { h2, c2h6, ch4, c2h4, c2h2, co, co2 } = values;

  const total = h2 + c2h6 + ch4 + c2h4 + c2h2 + co + co2;
  if (!total) return null;

  const percents = [
    (co / total) * 100,
    (co2 / total) * 100,
    (c2h4 / total) * 100,
    (h2 / total) * 100,
    (ch4 / total) * 100,
    (c2h2 / total) * 100,
    (c2h6 / total) * 100,
  ];

  const points = getHeptagonOuterPoints();

  let x = 0;
  let y = 0;

  for (let i = 0; i < 7; i++) {
    x += points[i][0] * (percents[i] / 100);
    y += points[i][1] * (percents[i] / 100);
  }

  return [x, y];
}

// ==========================
// ViewBox — expanded to accommodate labels outside vertices
// ==========================
export function getHeptagonViewBox() {
  return "-80 -50 844.8 829.32";
}

